§eImport everything from a chest§r
§bvar c = side("up");
function tick() { if (c) c.pull(); }§r

§eKeep 64 coal in a furnace§r
§bvar f = side("north");
function tick() {
  if (!f) return;
  var need = 64 - f.count("minecraft:coal");
  if (need > 0) f.push("minecraft:coal", need);
}§r

§eAuto-craft when low§r
§bfunction tick() {
  if (net.count("minecraft:stick") < 64)
    net.craft("minecraft:stick", 64);
}§r

§eMove between two chests§r
§bvar a = side("up"), b = side("down");
function tick() { if (a && b) a.move(b); }§r
